#!/usr/bin/env bash
# Build the flat AArch64 blob that the Go patcher adds to a static Go program and
# generate the Go source that embeds it.
#
# usage: build.sh [output-dir]
#   output-dir defaults to native/gopatch. The generated files are:
#     <out>/gosys.bin       the raw blob (kept for tests and inspection)
#     <out>/gosys_blob.go   the same bytes, with the entry offset and scratch size
#
# Needs aarch64-linux-gnu-gcc and binutils (apt: gcc-aarch64-linux-gnu).
set -euo pipefail

here=$(cd "$(dirname "$0")" && pwd)
out=${1:-$(cd "$here/../gopatch" && pwd)}
mkdir -p "$out"

cc=${CC_AARCH64:-aarch64-linux-gnu-gcc}
ld=${LD_AARCH64:-aarch64-linux-gnu-ld}
objcopy=${OBJCOPY_AARCH64:-aarch64-linux-gnu-objcopy}
nm=${NM_AARCH64:-aarch64-linux-gnu-nm}
objdump=${OBJDUMP_AARCH64:-aarch64-linux-gnu-objdump}

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

# -mcmodel=tiny and -fno-pic make every reference to the header and to the
# literals an adr/literal load, so the blob can be copied to a 64-byte aligned
# address: an adrp would assume the page offset of the linked address.
"$cc" -std=gnu11 -O2 -Wall -Wextra -Werror \
  -ffreestanding -fno-builtin -nostdlib -fno-pic -fno-pie -fvisibility=hidden \
  -fno-stack-protector -fno-asynchronous-unwind-tables -fno-unwind-tables \
  -fno-tree-loop-distribute-patterns \
  -mcmodel=tiny -mgeneral-regs-only -mno-outline-atomics \
  -ffixed-x18 -ffixed-x28 \
  -c "$here/gosys.c" -o "$tmp/gosys.o"
"$ld" -T "$here/gosys.ld" -nostdlib -o "$tmp/gosys.elf" "$tmp/gosys.o"
"$objcopy" -O binary "$tmp/gosys.elf" "$tmp/gosys.bin"

if [ -n "$("$nm" -u "$tmp/gosys.elf")" ]; then
  echo "build.sh: gosys.c needs symbols it does not define:" >&2
  "$nm" -u "$tmp/gosys.elf" >&2
  exit 1
fi
if "$objdump" -d "$tmp/gosys.elf" | grep -q -w adrp; then
  echo "build.sh: gosys.c uses adrp, which cannot be relocated to an arbitrary address" >&2
  exit 1
fi

entry=$("$nm" "$tmp/gosys.elf" | awk '$3 == "oc_stub_entry" {print $1}')
if [ -z "$entry" ]; then
  echo "build.sh: oc_stub_entry is missing" >&2
  exit 1
fi
entry=$((16#$entry))
if [ "$entry" -ne 64 ]; then
  echo "build.sh: oc_stub_entry is at $entry, expected 0x40" >&2
  exit 1
fi
[ "$(head -c 8 "$tmp/gosys.bin")" = "OCGOSYS1" ] || {
  echo "build.sh: the header is not first in the blob" >&2
  exit 1
}

size=$(wc -c < "$tmp/gosys.bin")
cp "$tmp/gosys.bin" "$out/gosys.bin"

{
  echo "// Code generated by native/gosys/build.sh; DO NOT EDIT."
  echo
  echo "package main"
  echo
  echo "const gosysEntryOff = $entry"
  echo "const gosysScratchSize = 65600"
  echo
  echo "var gosysBlob = []byte{"
  od -An -v -tx1 "$tmp/gosys.bin" |
    tr -s ' ' '\n' |
    sed -e '/^$/d' -e 's/^/0x/' -e 's/$/,/' |
    paste -sd' ' - |
    fold -s -w 96 |
    sed -e 's/^/\t/'
  echo "}"
} > "$out/gosys_blob.go"

echo "build.sh: $out/gosys.bin ($size bytes, entry $entry)"
